/* The engine talks to the network straight through libc socket()/connect().
 * Offline, connect() blocks until the OS gives up, and the game does it on the
 * frame thread -- one timeout per frame, which is why fps slides down to zero
 * and the whole UI freezes with the slot stuck red. Refuse the connection
 * immediately so the engine takes its "no network" path at once. */
static int net_connect_refuse(long fd, long addr, long len) {
  (void)fd; (void)addr; (void)len;
  /* A bare -1 leaves errno at whatever the last call set, and the engine then
   * treats the failure as transient and retries every frame. A definitive
   * "server refused" makes the caller give up on the spot. */
  errno = ECONNREFUSED;
  return -1;
}
